const $=s=>document.querySelector(s);
const lessons=[
{id:'g1',title:'第一句日语：A は B です',topic:'判断句',desc:'从「我是学生」开始，认识日语的基本句子。',rule:'A は B です表示「A 是 B」。は提示话题，作助词时读作 wa；です使表达礼貌。日语通常把谓语放在句末。',examples:[['わたしは学生です。','わたしは がくせいです。 / 我是学生。'],['田中さんは先生です。','たなかさんは せんせいです。 / 田中先生是老师。']],tip:'「さん」是敬称，通常不加在自己的名字后。日语在上下文清楚时可以省略「わたしは」。',q:'「我是学生」应该怎么说？',options:['わたしは学生です。','わたしを学生です。','わたしで学生です。'],answer:0,why:'は用于提示「我」这个话题，です用于礼貌地作出判断。'},
{id:'g2',title:'否定与疑问：ではありません／か',topic:'判断句',desc:'学会说「不是」，再试着提出一个问题。',rule:'名词判断句的礼貌否定是「名词＋ではありません」，日常也常用「じゃありません」。句末加「か」可以构成疑问句。',examples:[['わたしは先生ではありません。','我不是老师。'],['学生ですか。','がくせいですか。 / 你是学生吗？']],tip:'回答可以用「はい、そうです」（是的）或「いいえ、違います」（不，不是）。',q:'「不是学生」的礼貌表达是？',options:['学生でした。','学生ではありません。','学生ですか。'],answer:1,why:'ではありません是否定；でした是过去肯定；ですか用于提问。'},
{id:'g3',title:'指示词：これ・それ・あれ',topic:'基础表达',desc:'这个、那个、那边那个，表达眼前的事物。',rule:'これ指靠近说话者的东西，それ指靠近听话者的东西，あれ指离双方都远的东西。后面直接接名词时，要用この・その・あの。',examples:[['これは本です。','これは ほんです。 / 这是书。'],['この本はわたしの本です。','このほんは わたしのほんです。 / 这本书是我的书。']],tip:'これ本是错误的；「这个」可以单独用これ，「这本书」要用この本。',q:'「这本书」应该用？',options:['これ本','この本','ここ本'],answer:1,why:'この后面要接名词；これ本身是代词。'},
{id:'g4',title:'助词入门：の・も・と',topic:'助词',desc:'连接名词，表达所属、相同和并列。',rule:'「A の B」表示所属或修饰关系；も表示「也」，在简单判断句中可以替代は；と连接名词，表示「和」。',examples:[['これはわたしの本です。','これは わたしのほんです。 / 这是我的书。'],['わたしも学生です。','わたしも がくせいです。 / 我也是学生。'],['パンと水を買います。','パンと みずを かいます。 / 买面包和水。']],tip:'の不仅表达所有权，也可修饰名词，如「日本語の先生」（日语老师）。',q:'「我也是学生」应填：わたし（　）学生です。',options:['の','と','も'],answer:2,why:'も表示「也」，此处替代提示话题的は。'},
{id:'g5',title:'动词礼貌体：ます・ません',topic:'动词',desc:'学习说「吃」「喝」「学习」以及否定表达。',rule:'动词ます形是礼貌表达。ます表示非过去肯定，ません表示非过去否定；ました表示过去肯定，ませんでした表示过去否定。不同动词的ます形变化规则不同，本课先记常用形式。',examples:[['毎日、日本語を勉強します。','まいにち、にほんごを べんきょうします。 / 每天学习日语。'],['昨日、勉強しませんでした。','きのう、べんきょうしませんでした。 / 昨天没有学习。']],tip:'ます既可表示习惯，也可表示将来的动作；时间由语境或时间词帮助判断。',q:'「昨天喝了水」应填：昨日、水を飲み（　）。',options:['ます','ました','ません'],answer:1,why:'昨日表示过去，肯定的礼貌过去式用ました。'},
{id:'g6',title:'动作的对象与地点：を・で',topic:'助词',desc:'表达「喝什么」和「在哪里做某事」。',rule:'を标记动作的直接对象，作为助词时通常读作 o。で标记动作发生的地点。基本语序是「地点＋で＋对象＋を＋动词」。',examples:[['水を飲みます。','みずを のみます。 / 喝水。'],['図書館で日本語を勉強します。','としょかんで にほんごを べんきょうします。 / 在图书馆学习日语。']],tip:'动作发生的地点常用で；表示人或物的存在地点则常用に，后面的存在句课程会详细讲解。',q:'「在家看书」应填：家（　）本を読みます。',options:['を','で','の'],answer:1,why:'で标记「读书」这个动作发生的地点。'},
{id:'g7',title:'时间与方向：に・へ',topic:'助词',desc:'说清几点出发，以及去哪里。',rule:'に可以标记具体时间点，也可以标记移动的目的地；へ提示移动方向，作为助词时读作 e。「今日」「毎日」等时间词通常不接に。',examples:[['七時に起きます。','しちじに おきます。 / 七点起床。'],['学校へ行きます。','がっこうへ いきます。 / 去学校。']],tip:'「学校に行きます」也正确。表达移动时，に侧重到达点，へ侧重方向。',q:'「七点起床」应填：七時（　）起きます。',options:['で','を','に'],answer:2,why:'具体时间点后可以加に，提示动作发生的时间。'},
{id:'g8',title:'い形容词：おいしい・高い',topic:'形容词',desc:'描述味道、价格和大小。',rule:'い形容词可以直接修饰名词，如「高い本」。礼貌句末可加です。否定时把词尾い改为くない，过去肯定改为かった，再加です。',examples:[['このパンはおいしいです。','这个面包很好吃。'],['この本は高くないです。','このほんは たかくないです。 / 这本书不贵。'],['昨日は暑かったです。','きのうは あつかったです。 / 昨天很热。']],tip:'「いい」（好的）变化时用「よい」的词干：よくない、よかった。「きれい」虽然以い结尾，却是な形容词。',q:'「不贵」应选？',options:['高いではありません','高くないです','高かったです'],answer:1,why:'い形容词否定：去掉词尾い，再加くないです。'},
{id:'g9',title:'な形容词：静か・好き',topic:'形容词',desc:'表达安静、便利，以及自己的喜好。',rule:'な形容词修饰名词时加な，如「静かな町」。在句末用「静かです」，否定用「静かではありません」。常见的「好き」是な形容词，喜欢的对象常用が提示。',examples:[['ここは静かな町です。','ここは しずかなまちです。 / 这里是安静的小镇。'],['わたしは日本語が好きです。','わたしは にほんごが すきです。 / 我喜欢日语。']],tip:'い形容词和な形容词变化不同，应把词的类别一起记。',q:'「安静的房间」是？',options:['静かい部屋','静か部屋','静かな部屋'],answer:2,why:'な形容词修饰名词需要加な：静かな部屋。'},
{id:'g10',title:'存在句：あります・います',topic:'基础表达',desc:'表达「哪里有什么」和「谁在哪里」。',rule:'一般用あります表示无生命事物的存在，用います表示人和动物的存在。基本句型：「地点＋に＋事物／人＋が＋あります／います」。',examples:[['机の上に本があります。','つくえのうえに ほんが あります。 / 桌上有一本书。'],['教室に先生がいます。','きょうしつに せんせいが います。 / 教室里有老师。']],tip:'「本は机の上にあります」表示「书在桌上」。存在的地点用に，活动的地点常用で。',q:'「公园里有猫」应填：公園に猫が（　）。',options:['います','あります','です'],answer:0,why:'猫是动物，通常用います表示其存在。'},
{id:'g11',title:'て形与请求：〜てください',topic:'动词',desc:'学会说「请看」「请写」，理解て形变化。',rule:'て形用于连接动作或接续表达。二类动词去る加て（食べる→食べて）；する→して，来る→来て。一类动词按结尾变化：う・つ・る→って，む・ぶ・ぬ→んで，く→いて，ぐ→いで，す→して。「行く→行って」是例外。',examples:[['この本を読んでください。','このほんを よんでください。 / 请读这本书。'],['名前を書いてください。','なまえを かいてください。 / 请写下名字。']],tip:'不是所有以る结尾的动词都是二类动词。如帰る是一类动词，て形是帰って。需要查词典并记类别。',q:'「読む」的て形是？',options:['読みて','読んで','読って'],answer:1,why:'読む是一类动词，词尾む变成んで，因此是読んで。'},
{id:'g12',title:'正在做与想做：ています・たい',topic:'动词',desc:'表达眼下的动作与自己的愿望。',rule:'「动词て形＋います」可以表示正在进行的动作，也有表示结果状态等用法。「ます形去ます＋たいです」表达自己想做某事。たい按い形容词规则变化。',examples:[['今、日本語を勉強しています。','いま、にほんごを べんきょうしています。 / 现在正在学习日语。'],['日本へ行きたいです。','にほんへ いきたいです。 / 我想去日本。']],tip:'ている并非总是「正在」，如「結婚しています」表示已婚状态。たい通常直接表达说话者自己的愿望。',q:'「想吃」应选？',options:['食べてです','食べるたいです','食べたいです'],answer:2,why:'食べます去掉ます，再加たいです，得到食べたいです。'}
];
const kanaRows=[['あいうえお','アイウエオ',['a','i','u','e','o']],['かきくけこ','カキクケコ',['ka','ki','ku','ke','ko']],['さしすせそ','サシスセソ',['sa','shi','su','se','so']],['たちつてと','タチツテト',['ta','chi','tsu','te','to']],['なにぬねの','ナニヌネノ',['na','ni','nu','ne','no']],['はひふへほ','ハヒフヘホ',['ha','hi','fu','he','ho']],['まみむめも','マミムメモ',['ma','mi','mu','me','mo']],['や ゆ よ','ヤ ユ ヨ',['ya','','yu','','yo']],['らりるれろ','ラリルレロ',['ra','ri','ru','re','ro']],['わ   を','ワ   ヲ',['wa','','','','wo']],['ん    ','ン    ',['n','','','','']]];
const voicedRows=[['がぎぐげご','ガギグゲゴ',['ga','gi','gu','ge','go']],['ざじずぜぞ','ザジズゼゾ',['za','ji','zu','ze','zo']],['だぢづでど','ダヂヅデド',['da','ji','zu','de','do']],['ばびぶべぼ','バビブベボ',['ba','bi','bu','be','bo']],['ぱぴぷぺぽ','パピプペポ',['pa','pi','pu','pe','po']]];
let state={completed:[],seen:[],attempts:0,correct:0,days:[]},storageOK=true;
try{const saved=JSON.parse(localStorage.getItem('hajime-study-v1'));if(saved&&Array.isArray(saved.completed)&&Array.isArray(saved.seen)&&Array.isArray(saved.days))state={...state,...saved};}catch{storageOK=false;}
let page='home',kanaMode=0,kanaSet='basic',quizIndex=0,quizAnswered=false,quizType='grammar',quizRound=0;
const today=()=>new Date().toLocaleDateString('sv-SE');
function save(){if(!state.days.includes(today()))state.days.push(today());try{localStorage.setItem('hajime-study-v1',JSON.stringify(state));}catch{storageOK=false;toast('浏览器无法保存进度，本次学习仍可继续。');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function speak(text){if(!('speechSynthesis'in window)){toast('此浏览器不支持语音，请使用支持语音的浏览器。');return;}const voices=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith('ja'));if(!voices.length){toast('未检测到日语语音，请在系统语音设置中安装日语语音后重试。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.voice=voices[0];u.rate=.78;u.onerror=()=>toast('发音未能播放，请检查系统日语语音。');speechSynthesis.speak(u);}
if('speechSynthesis'in window)speechSynthesis.getVoices();
function title(en,name,desc){return `<div class="page-title"><div class="container"><div class="eyebrow">${en}</div><h1>${name}</h1><p>${desc}</p></div></div>`;}
function lessonTiles(items){return `<div class="lesson-list">${items.map(l=>`<button class="lesson-tile" data-lesson="${l.id}"><span class="label">LESSON ${String(lessons.indexOf(l)+1).padStart(2,'0')} · ${l.topic}</span><h3>${l.title}</h3><p>${l.desc}</p><span class="meta">${state.completed.includes(l.id)?'✓ 已学完 · 可以复习':'讲解 + 例句 + 随堂练习'} <span style="float:right">→</span></span></button>`).join('')}</div>`;}
function renderHome(){const next=lessons.find(l=>!state.completed.includes(l.id))||lessons[0];return `<div class="hero"><img class="art" src="landscape.svg" alt="樱花、富士山与湖面的原创插画"><div class="container"><div class="eyebrow">A NEW LANGUAGE. A NEW BEGINNING.</div><h1>从第一声，<br>到第一句。</h1><p>不必有基础，只需要一点好奇。<br>从五十音到日常表达，让日语学习有路可循。</p><button class="primary" data-page="kana">开启第一课 <span>→</span></button><button class="secondary" data-scroll="roadmap">了解学习路线</button></div><span class="hero-note">はじめの一歩 · 初见，从这里开始</span></div><div class="quick"><div class="container"><button data-page="kana"><span class="icon">あ</span><span><strong>认识五十音</strong><small>听见日语的第一声</small></span></button><button data-page="lessons"><span class="icon">本</span><span><strong>循序学课程</strong><small>一步一步，打好基础</small></span></button><button data-page="grammar"><span class="icon">文</span><span><strong>理解日语语法</strong><small>从单词走向完整的句子</small></span></button><button data-page="practice"><span class="icon">✎</span><span><strong>练习与巩固</strong><small>让每次学习都有回响</small></span></button></div></div><section class="container"><div class="sectionhead"><h2>从这里开始 <small>START YOUR JOURNEY</small></h2><button data-page="lessons">查看全部课程 ↗</button></div><div class="homegrid"><div class="cards"><button class="course-card" data-page="kana"><div class="course-art"><b>あ</b></div><div class="course-info"><span class="label">01 / 发音入门</span><h3>五十音，日语的起点</h3><p>平假名与片假名<br>认读、聆听与记忆</p><div class="meta"><span>46 个基础假名</span><span>开始学习 →</span></div></div></button><button class="course-card" data-lesson="g1"><div class="course-art t2"><b>は</b></div><div class="course-info"><span class="label">02 / 核心语法</span><h3>把单词连成第一句话</h3><p>认识判断句与助词<br>理解日语表达的顺序</p><div class="meta"><span>12 节入门课程</span><span>进入课堂 →</span></div></div></button><button class="course-card" data-lesson="g12"><div class="course-art t3"><b>こんにちは</b></div><div class="course-info"><span class="label">03 / 日常表达</span><h3>说说自己的日常</h3><p>描述动作与愿望<br>从理解到开口表达</p><div class="meta"><span>基础表达练习</span><span>试着表达 →</span></div></div></button></div><aside class="notice"><span class="day">YOUR DAILY STUDY</span><h3>今天，也前进一步</h3><h4>${state.completed.length?'继续你的日语旅程':'每天 20 分钟，养成学习习惯'}</h4><p>建议：5 分钟复习假名，10 分钟学习语法，5 分钟练习。<br>已完成 ${state.completed.length} / 12 节入门课程</p><button class="primary" data-lesson="${next.id}">${state.completed.length?'继续学习':'学习第一句日语'} <span>→</span></button></aside></div></section><section class="paper" id="roadmap"><div class="container"><div class="sectionhead"><h2>有方向，学得更从容 <small>LEARNING ROADMAP</small></h2><span class="more">零基础 → N5 学习路线</span></div><div class="route"><div class="route-item"><span class="num">01</span><h3>先认识声音与文字</h3><p>平假名、片假名、浊音与半浊音。搭配认读练习，建立发音基础。</p><small>建议第 1–2 周 · 已提供</small></div><div class="route-item"><span class="num">02</span><h3>用语法组织第一句话</h3><p>判断句、指示词与基本助词。用中文理解规则，再读日语例句。</p><small>建议第 3–4 周 · 已提供</small></div><div class="route-item"><span class="num">03</span><h3>理解动作，描述日常</h3><p>动词、形容词、存在句与て形。通过练习巩固语法和表达。</p><small>建议第 5–8 周 · 已提供</small></div><div class="route-item"><span class="num">04</span><h3>继续拓展 N5 基础</h3><p>补充词汇、汉字、听力与阅读，以及更多语法和综合练习。</p><small>后续扩充 · 当前为入门版</small></div></div></div></section><section class="container sentence"><div><div class="eyebrow">A SENTENCE A DAY</div><h2 style="font-family:serif;font-weight:400">今天，学会介绍自己。</h2><p>は提示话题，です让表达更礼貌。<br>从一句简单的话开始，理解日语的句子结构。</p><button class="more" data-lesson="g1">看看这句话的语法 →</button></div><blockquote><span lang="ja">わたしは学生です。</span><button class="speak" data-speak="わたしは学生です。" aria-label="播放例句">▷ 听发音</button><small>watashi wa gakusei desu · 我是学生。</small></blockquote></section>`;}
function renderKana(){const rows=kanaSet==='basic'?kanaRows:voicedRows;return title('THE FIRST SOUND','五十音入门','点击假名聆听日语发音；切换平假名与片假名，再用认读练习检验记忆。')+`<section class="container page-section"><div class="toolbar"><button class="chip ${kanaMode===0?'selected':''}" data-mode="0">平假名 ひらがな</button><button class="chip ${kanaMode===1?'selected':''}" data-mode="1">片假名 カタカナ</button><button class="chip ${kanaSet==='basic'?'selected':''}" data-set="basic">清音</button><button class="chip ${kanaSet==='voiced'?'selected':''}" data-set="voiced">浊音 / 半浊音</button><button class="chip" data-page="practice" data-quiz="kana">认读练习 →</button></div><div class="hint">基础假名共 46 个。「五十音」是表格的传统称呼。罗马字辅助认读；を在作助词时读 o，は在作助词时读 wa。点读使用系统日语合成语音，需安装日语语音包。已点读 ${state.seen.length} 个基础假名。</div><div class="kana-grid">${rows.map(row=>Array.from(row[kanaMode]).map((k,i)=>k===' '?'<div class="kana-cell empty"></div>':`<button class="kana-cell" data-kana="${k}" data-base="${row[0][i]}" aria-label="${k}，${row[2][i]}，播放发音"><b lang="ja">${k}</b><small>${row[2][i]}</small></button>`).join('')).join('')}</div><p class="completion-note">学习提示：每天记一到两行，先听，再跟读，最后遮住罗马字自行认读。</p></section>`;}
function renderLessons(grammar=false){return title(grammar?'UNDERSTAND THE SENTENCE':'STEP BY STEP',grammar?'语法课堂':'系统课程',grammar?'语法是表达的骨架。读懂规则，观察例句，再通过一道题确认自己真正理解。':'先熟悉假名，再按顺序学习以下 12 节入门课。每节含中文讲解、日语例句和随堂练习。')+`<section class="container page-section">${grammar?'<div class="toolbar" id="grammarFilters">'+['全部','判断句','助词','动词','形容词','基础表达'].map((t,i)=>`<button class="chip ${i===0?'selected':''}" data-filter="${t}">${t}</button>`).join('')+'</div>':'<div class="hint">建议先完成五十音认读，再学习第 1–4 课。当前课程为 N5 学习路线的入门部分；完整备考还需补充词汇、汉字、听力和阅读。</div>'}<div id="tiles">${lessonTiles(lessons)}</div></section>`;}
function getKanaQuestion(){const list=kanaRows.flatMap(r=>Array.from(r[0]).map((k,i)=>({k,r:r[2][i]}))).filter(x=>x.k!==' ');const cur=list[(quizIndex*7+quizRound*3)%list.length];let opts=[cur.r,...list.filter(x=>x.r!==cur.r).slice((quizIndex*3)%38,(quizIndex*3)%38+3).map(x=>x.r)];const shift=quizIndex%4;opts=opts.slice(shift).concat(opts.slice(0,shift));return{q:`「${cur.k}」的读音是？`,options:opts,answer:opts.indexOf(cur.r),why:`「${cur.k}」读作 ${cur.r}。先听，再跟读一次。`,sound:cur.k};}
function getQuestion(){return quizType==='kana'?getKanaQuestion():lessons[(quizIndex+quizRound)%lessons.length];}
function renderPractice(){quizAnswered=false;const q=getQuestion();return title('PRACTICE MAKES PROGRESS','练习中心','先尝试回忆，再查看解释。做错的题也是了解自己的一次机会。')+`<section class="container page-section"><div class="toolbar"><button class="chip ${quizType==='grammar'?'selected':''}" data-quiztype="grammar">语法巩固</button><button class="chip ${quizType==='kana'?'selected':''}" data-quiztype="kana">假名认读</button></div><div class="quizbox"><span class="label">${quizType==='grammar'?'GRAMMAR':'KANA'} / 第 ${quizIndex+1} 题 · 本组 10 题</span><h2>${q.q}</h2><div class="answers">${q.options.map((o,i)=>`<button data-quizanswer="${i}">${o}</button>`).join('')}</div><div class="feedback" id="quizFeedback" role="status">请选择一个答案。</div><button class="primary" id="nextQuestion" hidden>下一题 →</button></div></section>`;}
function renderProgress(){const pct=Math.round(state.completed.length/lessons.length*100);return title('YOUR LEARNING ARCHIVE','学习档案','每一节学过的课，每一次认真练习，都值得记录。')+`<section class="container page-section"><div class="stats"><div class="stat"><b>${state.completed.length}<span> / 12</span></b><span>已完成入门课</span></div><div class="stat"><b>${state.attempts?Math.round(state.correct/state.attempts*100):0}<span>%</span></b><span>练习正确率 · ${state.attempts} 次作答</span></div><div class="stat"><b>${state.days.length}</b><span>累计学习天数</span></div></div><div class="sectionhead"><h2>课程进度 <small>${pct}% COMPLETE</small></h2><button id="exportProgress">导出学习记录 ↗</button></div><div class="bar"><div style="width:${pct}%"></div></div>${lessons.map(l=>`<div class="progress-row"><span>${state.completed.includes(l.id)?'✓':'○'}　${l.title}</span><button data-lesson="${l.id}">${state.completed.includes(l.id)?'复习':'学习'} →</button></div>`).join('')}<p class="completion-note">已点读 ${state.seen.length} / 46 个基础假名。${storageOK?'进度保存在当前浏览器，暂不跨设备同步。':'当前浏览器无法持久保存，请导出学习记录。'}正确率包含随堂练习和练习中心的首次作答。</p></section>`;}
function render(scroll=true){$('#view').innerHTML=page==='home'?renderHome():page==='kana'?renderKana():page==='lessons'?renderLessons():page==='grammar'?renderLessons(true):page==='practice'?renderPractice():renderProgress();document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function openLesson(id){const l=lessons.find(x=>x.id===id);$('#lessonBody').innerHTML=`<span class="label">LESSON ${String(lessons.indexOf(l)+1).padStart(2,'0')} / ${l.topic}</span><h2>${l.title}</h2><h3>理解规则</h3><p>${l.rule}</p><h3>观察例句</h3>${l.examples.map(([ja,zh])=>`<div class="example"><b lang="ja">${ja}</b><button class="speak" data-speak="${ja}">▷ 听发音</button><small>${zh}</small></div>`).join('')}<h3>记住这一点</h3><p>${l.tip}</p><div class="exercise"><span class="label">CHECK YOUR UNDERSTANDING</span><p>${l.q}</p><div class="answers">${l.options.map((o,i)=>`<button data-lessonanswer="${i}" data-id="${l.id}">${o}</button>`).join('')}</div><div class="feedback" id="lessonFeedback" role="status"></div></div><button class="primary complete" id="completeLesson" data-id="${l.id}">学完了，记录进度 ✓</button><p class="completion-note">建议读完讲解并完成随堂练习后，再标记学完。</p>`;$('#lessonDialog').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.page){if(d.quiz)quizType=d.quiz;page=d.page;render();}
if(d.scroll){if(page!=='home'){page='home';render();}document.getElementById(d.scroll)?.scrollIntoView({behavior:'smooth'});}
if(d.lesson)openLesson(d.lesson);
if(d.speak)speak(d.speak);
if(d.kana){speak(d.kana);if(kanaRows.some(r=>r[0].includes(d.base))&&!state.seen.includes(d.base)){state.seen.push(d.base);save();}}
if(d.mode!==undefined){kanaMode=Number(d.mode);render(false);}if(d.set){kanaSet=d.set;render(false);}
if(d.filter){document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));$('#tiles').innerHTML=lessonTiles(d.filter==='全部'?lessons:lessons.filter(l=>l.topic===d.filter));}
if(d.quiztype){quizType=d.quiztype;quizIndex=0;render(false);}
if(d.lessonanswer!==undefined){const l=lessons.find(x=>x.id===d.id);const answered=b.parentElement.dataset.answered;if(answered)return;b.parentElement.dataset.answered='yes';const ok=Number(d.lessonanswer)===l.answer;state.attempts++;if(ok)state.correct++;save();b.classList.add(ok?'correct':'wrong');b.parentElement.children[l.answer].classList.add('correct');$('#lessonFeedback').textContent=`${ok?'✓ 回答正确。':'再记一次：'} ${l.why}`;}
if(d.quizanswer!==undefined&&!quizAnswered){quizAnswered=true;const q=getQuestion(),ok=Number(d.quizanswer)===q.answer;state.attempts++;if(ok)state.correct++;save();b.classList.add(ok?'correct':'wrong');b.parentElement.children[q.answer].classList.add('correct');$('#quizFeedback').textContent=`${ok?'✓ 回答正确。':'再记一次：'} ${q.why}`;$('#nextQuestion').hidden=false;if(quizIndex===9)$('#nextQuestion').textContent='完成本组练习 ✓';}
if(b.id==='nextQuestion'){if(quizIndex===9){quizRound++;quizIndex=0;toast('本组 10 题已完成！学习记录已更新。');page='progress';}else quizIndex++;render(false);}
if(b.id==='completeLesson'){if(!state.completed.includes(d.id))state.completed.push(d.id);save();$('#lessonDialog').close();render(false);toast('已记入学习档案，继续保持。');}
if(b.classList.contains('close'))$('#lessonDialog').close();
if(b.id==='progressLink'){page='progress';render();}
if(b.id==='exportProgress'){const blob=new Blob([JSON.stringify({...state,site:'初见日语',exportedAt:new Date().toISOString(),completedLessonTitles:lessons.filter(l=>state.completed.includes(l.id)).map(l=>l.title)},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='初见日语-学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
});
document.addEventListener('click',e=>{const a=e.target.closest('a[href="#roadmap"]');if(a){e.preventDefault();if(page!=='home'){page='home';render();}$('#roadmap').scrollIntoView({behavior:'smooth'});}});
$('#lessonDialog').addEventListener('click',e=>{if(e.target===$('#lessonDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render(false);
